using System;using System.Drawing;using System.Diagnostics;using System.Runtime.InteropServices;using Bemo;
class ImageResources {
 [DllImport("user32.dll")] static extern uint GetGuiResources(IntPtr p,uint kind);
 static void Cycle(){var image=new Img(new Bitmap(1024,768));using(image.bitmap){using(var g=image.graphics)g.Clear(Color.CornflowerBlue);var cropped=image.crop(new Sz(600,400));using(cropped.bitmap){var scaled=cropped.resize(new Sz(240,160));using(scaled.bitmap){if(scaled.bitmap.GetPixel(20,20).ToArgb()!=Color.CornflowerBlue.ToArgb())throw new Exception("Preview pixel changed");}}if(!Object.ReferenceEquals(image,image.crop(image.size)))throw new Exception("Equal-size crop ownership changed");}}
 static int Main(){try {for(int i=0;i<20;i++)Cycle();uint gdi=GetGuiResources(Process.GetCurrentProcess().Handle,0);long before=Process.GetCurrentProcess().PrivateMemorySize64;int gen2=GC.CollectionCount(2);var sw=Stopwatch.StartNew();for(int i=0;i<1500;i++)Cycle();uint after=GetGuiResources(Process.GetCurrentProcess().Handle,0);long mem=Process.GetCurrentProcess().PrivateMemorySize64;Console.WriteLine("1500 full-size crop/resize cycles: {0} ms; GDI {1}->{2}; private MB {3}->{4}; Gen2 collections {5}",sw.ElapsedMilliseconds,gdi,after,before/1048576,mem/1048576,GC.CollectionCount(2)-gen2);if(after>gdi+2)throw new Exception("GDI growth");if(mem-before>64*1048576)throw new Exception("Native image memory growth");Console.WriteLine("PASS pixels, crop alias ownership, resource lifetime");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
